oxy_webhelp_navlinks = {"recover_db2-d39307e34761":{"topics":[{"title":"Recoverable range for Db2 database","shortdesc":"<p class=\"shortdesc\">The recoverable range for a Db2 database is a visual representation of the duration         within which you can recover a database to a specific point in time.<\/p>","href":"db2\/recoverable_range_db2.html","attributes":{"data-id":"recoverable_range_db2"},"menu":{"hasChildren":false},"tocID":"recoverable_range_db2-d39307e34772","topics":[]},{"title":"Db2 database restore in CDM","shortdesc":"<p class=\"shortdesc\">Db2 database restore in CDM supports restoring databases in standalone, DPF, and HADR         environments, covering both same-instance and cross-instance restore scenarios across CDM         versions 9.x.<\/p>","href":"db2\/db2_database_restore_cdm_v9.x.html","attributes":{"data-id":"db2_database_restore_cdm_v9.x"},"menu":{"hasChildren":false},"tocID":"db2_database_restore_cdm_v9.x-d39307e34783","next":"db2_database_restore_cdm_v9.x-d39307e34783"},{"title":"Db2 database recovery using <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides two Db2 recovery options, point-in-time and         end-of-backup, and supports recovering databases to the original, a different, or a new         database instance.<\/p>","href":"db2\/db2_db_recovery_using_rsc.html","attributes":{"data-id":"db2_db_recovery_using_rsc"},"menu":{"hasChildren":false},"tocID":"db2_db_recovery_using_rsc-d39307e34904","next":"db2_db_recovery_using_rsc-d39307e34904"},{"title":"Db2 database restore within a pureScale cluster","shortdesc":"<p class=\"shortdesc\">When maintaining continuity of operations and ensuring data integrity are crucial,         you can initiate database restoration within a pureScale cluster, thereby achieving seamless         data recovery and enhancing overall reliability.<\/p>","href":"db2\/db2_restore_purescale_cluster.html","attributes":{"data-id":"db2_restore_purescale_cluster"},"menu":{"hasChildren":false},"tocID":"db2_restore_purescale_cluster-d39307e34969","topics":[]},{"title":"Db2 cross-host recovery","shortdesc":"<p class=\"shortdesc\">You can restore a database to a host other than the original database host using Db2         cross-host recovery.<\/p>","href":"db2\/db2_cross_host_recovery.html","attributes":{"data-id":"db2_cross_host_recovery"},"menu":{"hasChildren":false},"tocID":"db2_cross_host_recovery-d39307e34980","next":"db2_cross_host_recovery-d39307e34980"},{"title":"Db2 data retrieval","shortdesc":"<p class=\"shortdesc\">Data retrieval methods such as db2_fetch_tool or db2_fetch_log_main ensure data         integrity and continuity by downloading the data and log backup images if a Db2 system         fails.<\/p>","href":"db2\/db2_data_retrieval.html","attributes":{"data-id":"db2_data_retrieval"},"menu":{"hasChildren":false},"tocID":"db2_data_retrieval-d39307e35024","next":"db2_data_retrieval-d39307e35024"},{"title":"Db2 external backup trigger","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enables you to initiate Db2 database backups using external tools         such as the Db2 CLI. This method provides control and flexibility over backup scheduling         because it does not rely on Rubrik-managed SLA Domain policies to trigger         backups.<\/p>","href":"db2\/db2_external_backup_trigger.html","attributes":{"data-id":"db2_external_backup_trigger"},"menu":{"hasChildren":false},"tocID":"db2_external_backup_trigger-d39307e35112","topics":[]}]}};